<template>
    <Head title="Cài đặt tài khoản" />

    <div class="settings-dashboard">
        <section class="settings-view settings-profile-block">
            <div class="view-header">
                <div class="view-title-wrap">
                    <div class="view-icon profile-icon"><UserRound :size="21" /></div>
                    <div><span class="section-kicker">TÀI KHOẢN</span><h2>Thông tin cá nhân</h2><p>Quản lý thông tin cá nhân và địa chỉ email của bạn.</p></div>
                </div>
                <Form action="/logout" method="post"><button type="submit" class="settings-logout"><i class="bi bi-box-arrow-right" /> Đăng xuất</button></Form>
